mapper.update:
UPDATE crm_youzan_annual_profile p
LEFT JOIN (
    SELECT
        COUNT(*) AS cnt,
        COALESCE(SUM(GREATEST(0, payment_fen - refunded_fen)), 0) AS total_fen,
        MIN(COALESCE(paid_at, ordered_at)) AS first_at,
        MAX(COALESCE(paid_at, ordered_at)) AS last_at
    FROM crm_youzan_annual_order_snapshot
    WHERE tenant_id = #{tenantId}
      AND shop_id = #{shopId}
      AND yz_open_id = #{yzOpenId}
      AND is_paid = 1
) agg ON 1 = 1
SET
    p.order_count = COALESCE(agg.cnt, 0),
    p.total_payment_fen = COALESCE(agg.total_fen, 0),
    p.first_order_at = agg.first_at,
    p.last_order_at = agg.last_at,
    p.synced_at = #{syncedAt}
WHERE p.tenant_id = #{tenantId}
  AND p.shop_id = #{shopId}
  AND p.yz_open_id = #{yzOpenId}

