SELECT 
FROM crm_youzan_annual_order_snapshot
WHERE tenant_id = #{tenantId}
  AND yz_open_id = #{yzOpenId}
  AND is_paid = 1

      AND shop_id = #{shopId}

  AND COALESCE(paid_at, ordered_at) >= #{yearStart}
  AND COALESCE(paid_at, ordered_at) < #{yearEnd}
ORDER BY COALESCE(paid_at, ordered_at) ASC, id ASC

SELECT DISTINCT linked.shop_id, linked.yz_open_id
FROM (
    SELECT shop_id, external_customer_id AS yz_open_id
    FROM crm_youzan_customer_link
    WHERE tenant_id = #{tenantId}
      AND customer_id = #{customerId}
    UNION
    SELECT source_app AS shop_id, external_id AS yz_open_id
    FROM crm_customer_identity
    WHERE tenant_id = #{tenantId}
      AND customer_id = #{customerId}
      AND identity_type = 'YOUZAN'
      AND status = 'LINKED'
    UNION
    SELECT shop_id, yz_open_id
    FROM crm_youzan_annual_profile
    WHERE tenant_id = #{tenantId}
      AND customer_id = #{customerId}
) linked
WHERE linked.shop_id IS NOT NULL AND linked.shop_id != ''
  AND linked.yz_open_id IS NOT NULL AND linked.yz_open_id != ''
ORDER BY linked.shop_id ASC, linked.yz_open_id ASC

SELECT COUNT(*) AS total_order_count, COALESCE(SUM(CASE WHEN is_paid = 1 THEN 1 ELSE 0 END), 0) AS paid_order_count, COALESCE(SUM(CASE WHEN is_paid = 1 THEN payment_fen ELSE 0 END), 0) AS total_payment_fen, COALESCE(SUM(CASE WHEN is_paid = 1 THEN refunded_fen ELSE 0 END), 0) AS total_refunded_fen, COALESCE(SUM(CASE WHEN is_paid = 1 THEN GREATEST(0, payment_fen - refunded_fen) ELSE 0 END), 0) AS net_spend_fen, MIN(CASE WHEN is_paid = 1 THEN COALESCE(paid_at, ordered_at) ELSE NULL END) AS first_order_at, MAX(CASE WHEN is_paid = 1 THEN COALESCE(paid_at, ordered_at) ELSE NULL END) AS last_order_at, MAX(synced_at) AS last_synced_at FROM crm_youzan_annual_order_snapshot WHERE tenant_id = #{tenantId} AND (
(shop_id = #{ident.shopId} AND yz_open_id = #{ident.yzOpenId})
)

SELECT 
FROM crm_youzan_annual_order_snapshot
WHERE tenant_id = #{tenantId}
  AND (

        (shop_id = #{ident.shopId} AND yz_open_id = #{ident.yzOpenId})

  )

      AND is_paid = 1

ORDER BY COALESCE(paid_at, ordered_at) DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT customer_id
FROM crm_youzan_customer_link
WHERE tenant_id = #{tenantId}
  AND shop_id = #{shopId}
  AND external_customer_id = #{yzOpenId}
LIMIT 1

SELECT share_key
FROM crm_annual_report
WHERE tenant_id = #{tenantId}
  AND customer_id = #{customerId}
  AND report_year = #{reportYear}
  AND status = 'ACTIVE'
ORDER BY id DESC
LIMIT 1

SELECT id, tenant_id, channel_type, openid_hash, unionid_hash, shop_id, yz_open_id,
       customer_id, mobile_hash, bound_via, created_at, updated_at
FROM crm_h5_c_identity_binding
WHERE tenant_id = #{tenantId}
  AND channel_type = #{channelType}
  AND openid_hash = #{openidHash}
LIMIT 1

